/* [MSG_USE 40 08 00] */
static void demon4_PhaserNauian(void)
{
    if (fv_warned != 1) {
        demon4_Say(N_Nauian, T_DEM4_033);
        fv_warned = 1;
    } else {
        demon4_Say(N_Nauian, T_DEM4_032);
        svc_Anim(0xA, N_bxfire, 0, 0, 2);
        svc_Sfx(N_V0SPOCKT);
        room.busy = 1;
        room.timers[2] = 7;
        room.timers[3] = 8;
        room.timers[4] = 7;
        room.timers[5] = 8;
    }
    return;
}

