/* [MSG_WALK_DONE 02 00 00] */
static void demon4_ShowSkull(void)
{
    uint16_t ax = 0;
    demon4_Say(N_Nauian, T_DEM4_036);
    ax = (uint16_t)demon4_Talk(KirkOnSkull);
    if (ax == 0) {
    } else {
        if (ax == 1) {
            goto L075F;
        }
        if (ax == 2) {
            goto L075F;
        }
        { demon4_part_09B9(); return; }
    }
    rv_score += 1;
    svc_Anim(8, N_takesk, 0x107, 0x8E, 0);
    svc_TakeItem(IT_SKULL);
    rv_taken_items &= 0xEF;
    rv_gave_skull = 1;
L075F:;
    return;
}

